mod solution;

fn main() {
    let cases = [
    (r#"[1,3,-1,-3,5,3,6,7]"#, r#"3,3,5,5,6,7"#),
    (r#"[4,2,12,3]"#, r#"12,12"#),
    (r#"
[4,2,12,3]
"#, r#"12,12"#),
    (r#"  
[1,3,-1,-3,5,3,6,7]
  "#, r#"3,3,5,5,6,7"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS monotonic-deque-window");
}
